import{z as i,x as l,o as t,c as d,q as A,j as s,D as B,d as E,s as o,S as n,b as e}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"分级上线：shadow 到全仓","description":"","frontmatter":{"title":"分级上线：shadow 到全仓","date":"2026-09-18T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/paper-to-live-staging.md","filePath":"quant/paper-to-live-staging.md","lastUpdated":1791413859000}'),p={name:"quant/paper-to-live-staging.md"};function F(h,a,m,u,C,D){const r=l("Mermaid");return t(),d("div",null,[a[2]||(a[2]=A('<h1 id="分级上线-shadow-到全仓" tabindex="-1">分级上线：shadow 到全仓 <a class="header-anchor" href="#分级上线-shadow-到全仓" aria-label="Permalink to &quot;分级上线：shadow 到全仓&quot;">​</a></h1><div class="epigraph"><p>影子组合不花真钱，也买不到拒单、部分成交与排队；它验证的是定义，不是执行。</p><footer>—— 据 Arnott, Harvey and Markowitz, Journal of Financial Data Science, 2019；Almgren et al., Risk, 2005 整理</footer></div><p><a href="/quant/risk-overlay-cap">上一课</a>把触发器与恢复规则钉进政策层，组合在研究环境里已经三层齐备：权重、成本、风险。但所有数字产自同一个环境。分级上线把「验证过的定义」交给「不可控的执行」，台阶是 shadow 组合、小容量实盘、再逐步放大。环境分离的架构原则已在<a href="/quant/research-sim-prod">研究、模拟、实盘隔离</a>立过：晋级产生不可变版本、试验计数可数；本课是那套原则在单次研究上的执行手册，写每级的通过判据与回滚条件。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>一步跳到全仓，错在同时引入两类未知：执行未知——拒单、部分成交、排队、状态机 bug；规模未知——容量曲线是小账户校准的，AUM 一步到位后自身冲击当场改写入场价。两类未知搅在一条净值里，出了问题既不能归因也不能修。反过来，shadow 太久同样有错：影子不花真钱，「再观察一个月」永远有诱惑，影子期还容易被当成第三段样本内反复调参——影子成了另一种过拟合。台阶的目的由此而来：<strong>每级只引入一类新不确定性</strong>，其余全部冻结。</p><p><span class="marginnote">可以把它想象成新药临床试验的分期：一期先在少数受试者身上验证安全性，二期扩样看疗效，三期大规模验证——每一期只放开一类变量，出了问题才知道该怪谁。shadow、小容量、逐档放大对应的就是这三个阶段，只是「受试者」换成了真金白银。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p><strong>第一级 shadow。</strong> 冻结版本（代码哈希、特征定义、参数、声明的试验数 \\(N\\)）接实时数据，在与实盘同一套状态机与撮合假设里跑，不离开公司。通过判据预指定：与研究权益曲线的跟踪带、数据管道零缺失、时钟与日历一致。<strong>第二级小容量。</strong> 真账户、最小名义。判据是执行量而非收益：成交缺口对<a href="/quant/execution-cost-forecast-cap">成本预测</a>的残差带内——模型第一次接受真成交检验；完成率、对账一致、风控闸门无误触发。<strong>第三级放大。</strong> 沿<a href="/quant/strategy-capacity-decay">策略容量与冲击衰减</a>的 \\(\\mu_{\\mathrm{net}}(A)\\) 分档，每档预指定停留时间与指标带；带外自动回滚一级而不是停机——回滚是默认动作，停机是最后动作。每级晋级都产出新版本号，\\(N\\) 加一。</p><p><span class="marginnote">数字实例：小容量阶段若只跑 60 个交易日，日波动 1% 时，这段累计收益的随机波动幅度约为 \\(1\\% \\times \\sqrt{60} \\approx 7.7\\%\\)；而策略一个月的期望超额收益可能只有 1% 量级——收益信号完全淹在噪声里。这就是判据换成缺口残差、完成率这类每天可测成百上千次的执行量的原因：样本多，噪声才能平均掉。</span></p><p><span class="marginnote">每级停留时间至少覆盖信号最短决策周期的一个完整换手；否则连一次完整调仓都没看过就晋级，判据全落在「没发生过的事」上。</span></p>',10)),(t(),s(n,null,{default:B(()=>[o(r,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20FRZ%5B%22%E5%86%BB%E7%BB%93%E7%89%88%E6%9C%AC%EF%BC%9A%E4%BB%A3%E7%A0%81%2F%E7%89%B9%E5%BE%81%2F%E5%8F%82%E6%95%B0%2FN%22%5D%20--%3E%20SH%5B%22shadow%EF%BC%9A%E5%AE%9E%E6%97%B6%E6%95%B0%E6%8D%AE%2B%E6%A8%A1%E6%8B%9F%E6%92%AE%E5%90%88%22%5D%0A%20%20SH%20--%3E%20G1%7B%22%E8%B7%9F%E8%B8%AA%E5%B8%A6%E5%86%85%3F%20%E7%AE%A1%E9%81%93%E6%97%A0%E7%BC%BA%E5%A4%B1%3F%22%7D%0A%20%20G1%20--%3E%7C%E5%90%A6%7C%20FIX1%5B%22%E4%BF%AE%E6%89%A7%E8%A1%8C%EF%BC%8C%E4%B8%8D%E6%94%B9%E4%BF%A1%E5%8F%B7%22%5D%0A%20%20G1%20--%3E%7C%E6%98%AF%7C%20SM%5B%22%E5%B0%8F%E5%AE%B9%E9%87%8F%E5%AE%9E%E7%9B%98%22%5D%0A%20%20SM%20--%3E%20G2%7B%22%E7%BC%BA%E5%8F%A3%E6%AE%8B%E5%B7%AE%E5%B8%A6%E5%86%85%3F%20%E5%AF%B9%E8%B4%A6%E4%B8%80%E8%87%B4%3F%22%7D%0A%20%20G2%20--%3E%7C%E5%90%A6%7C%20RB1%5B%22%E5%9B%9E%E6%BB%9A%E4%B8%80%E7%BA%A7%22%5D%0A%20%20G2%20--%3E%7C%E6%98%AF%7C%20AMP%5B%22%E6%B2%BF%E5%AE%B9%E9%87%8F%E5%88%86%E6%A1%A3%E6%94%BE%E5%A4%A7%22%5D%0A%20%20AMP%20--%3E%20G3%7B%22%E6%8C%87%E6%A0%87%E5%B8%A6%E5%86%85%3F%22%7D%0A%20%20G3%20--%3E%7C%E5%90%A6%7C%20RB2%5B%22%E5%9B%9E%E6%BB%9A%E4%B8%80%E7%BA%A7%22%5D%0A%20%20G3%20--%3E%7C%E6%98%AF%7C%20FULL%5B%22%E4%B8%8B%E4%B8%80%E6%A1%A3%E6%88%96%E5%85%A8%E4%BB%93%22%5D%0A"})]),fallback:B(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("h2",{id:"机制",tabindex:"-1"},[E("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=e("p",null,[E("台阶有效靠控制变量。shadow 引入实时数据与时钟，小容量引入真实撮合，放大引入自身冲击与市场反应；每级观测到的偏差都能归因到刚引入的那一类，修复动作因此是局部的。放大的机制是"),e("strong",null,"校准"),E("而非验证：小容量实盘是估计冲击函数的数据源，短路径的夏普标准误大到没有判别力，所以判据必须设计成缺口残差、完成率这类高频可测量，而不是收益本身。影子期与模拟期的偏差用来修执行——状态机、日程、参与率——不用来回改信号；改信号则台阶全部清零重来，这是"),e("a",{href:"/quant/research-sim-prod"},"研究、模拟、实盘隔离"),E("的硬约束。")],-1)),a[5]||(a[5]=e("p",null,"偏差落在哪一层，决定台阶要不要清零：",-1)),(t(),s(n,null,{default:B(()=>[o(r,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20DEV%5B%22%E5%8F%B0%E9%98%B6%E4%B8%8A%E5%8F%91%E7%8E%B0%E5%81%8F%E5%B7%AE%22%5D%20--%3E%20ATTR%7B%22%E5%BD%92%E5%9B%A0%E5%88%B0%E5%88%9A%E5%BC%95%E5%85%A5%E7%9A%84%E9%82%A3%E7%B1%BB%EF%BC%9F%22%7D%0A%20%20ATTR%20--%3E%7C%22%E6%89%A7%E8%A1%8C%E5%B1%82%E5%9D%8F%E4%BA%86%22%7C%20FIX%5B%22%E4%BF%AE%E7%8A%B6%E6%80%81%E6%9C%BA%2F%E6%97%A5%E7%A8%8B%2F%E5%8F%82%E4%B8%8E%E7%8E%87%22%5D%0A%20%20FIX%20--%3E%20RETRY%5B%22%E5%BD%93%E5%89%8D%E7%BA%A7%E9%87%8D%E6%B5%8B%EF%BC%8C%E5%8F%B0%E9%98%B6%E4%BF%9D%E7%95%99%22%5D%0A%20%20ATTR%20--%3E%7C%22%E4%BF%A1%E5%8F%B7%E5%B1%82%E8%A6%81%E6%94%B9%22%7C%20SIG%5B%22%E6%94%B9%E5%AE%9A%E4%B9%89%2F%E5%8F%82%E6%95%B0%20%3D%20%E6%96%B0%E8%AF%95%E9%AA%8C%22%5D%0A%20%20SIG%20--%3E%20RESET%5B%22N%20%E5%8A%A0%E4%B8%80%EF%BC%8C%E5%8F%B0%E9%98%B6%E6%B8%85%E9%9B%B6%E9%87%8D%E8%B5%B0%22%5D%0A"})]),fallback:B(()=>[...a[1]||(a[1]=[E(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=A('<p><span class="marginnote">初学者容易把「前几笔都赚了」当成加速放大的证据。实际上小容量阶段的几笔盈亏几乎是纯噪声，就像连抛十次硬币全正面并不能证明硬币不公平。放大的依据只能是容量曲线与执行指标，与赚没赚无关——「用回测安慰自己」和「用浮盈加速」，是同一枚硬币的两面。</span></p><p>回滚与晋级共用同一组指标带：带的上侧是晋级判据，下侧是回滚触发，同一次冻结里对称写出。这让「回到上一级」成为一个不需要开会决定的技术动作，而不是一次挫败感驱动的政治决定。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>影子的撮合假设若比实盘乐观（中点成交、无拒单），所有判据失效——影子必须与实盘共享同一套状态机；由人盯盘点「假如成交」的不是影子，只是演练。放大不能因「前几笔赚了」加速：那是在用运气缩短停留时间，与用回测安慰自己是同一种错误。台阶中途市场制度切换，处理方式是回上一级重测，不是就地改参数硬扛。最后，台阶不是保险箱：它防的是「未知的未知集中爆发」，防不了 alpha 本身死亡——那是下一课监控的事。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>台阶原则：每级只引入一类新不确定性——实时数据、真实撮合、自身冲击。</li><li>判据设计成高频可测的执行量（跟踪带、缺口残差、完成率），收益不进判据：短路径没有统计效力。</li><li>回滚是默认动作，与晋级共用指标带；停机才进入研究账户走新试验。</li><li>影子必须与实盘同一套撮合假设；放大按 \\(\\mu_{\\mathrm{net}}(A)\\) 分档，不用盈亏加速。</li><li>出处：Arnott, Harvey and Markowitz, <em>JFDS</em>, 2019；架构原则见<a href="/quant/research-sim-prod">研究、模拟、实盘隔离</a>，冲击校准见<a href="/quant/sqrt-impact">线性与平方根冲击</a>。</li></ul>',6))])}const g=i(p,[["render",F]]);export{f as __pageData,g as default};
